"""Apply explicit independent-review corrections, preserving original v1 in audits."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
p=R/'data/question-batches/W01-L01.json';b=json.loads(p.read_text());updates={}
def change(page,num,options,explanations,stem=None,difficulty=None):
 updates[f'W01-L01-P{page:04d}-Q{num:02d}']=(options,explanations,stem,difficulty)
change(20,1,['Electric versus hydraulic actuation','Fixed versus mobile','Serial versus parallel','Rigid versus flexible'],['Actuation power source is a meaningful robotics classification but is not among this slide’s listed dimensions.','Fixed/mobile is explicitly listed.','Serial/parallel is explicitly listed.','Rigid/flexible is explicitly listed.'])
change(20,2,['A fixed base with links joined by actuated joints','A mobile base with an arm whose links are connected by actuated joints','A fixed platform connected through several closed-loop leg chains','A fixed base with links connected exclusively by passive joints'],['This is the older industrial-arm description printed on the slide.','This adds a mobile base, unlike the fixed-base description.','This is a parallel-platform structure, not the described links-and-actuated-joints arm.','The source explicitly specifies actuated, not exclusively passive, joints.'])
change(21,2,['The top platform','The fixed base itself','A single open-chain forearm ending at one wrist','The spherical-joint housings without a common platform'],['The legs connect the fixed base to the top platform.','The fixed base is the stationary lower member, not the upper member supported by the legs.','That describes a serial-chain member rather than the drawing’s parallel platform.','The joint housings terminate the legs, but the drawing shows them attached to a common top platform.'])
change(22,4,['Extra flexibility or working volume','Higher wrist-orientation resolution without changing the reachable region','Higher structural stiffness from adding base motion as the main stated benefit','A smaller reachable region to constrain arm travel'],['The slide explicitly names flexibility and working volume.','Resolution is not the stated reason, and added base motion can enlarge reach.','The slide does not identify stiffness as the reason for the mobile mounting.','The stated working-volume benefit is not a reduction of reachable region.'])
change(23,3,['They form a wrist that orients the end-effector','They primarily place the wrist center while the first three orient the tool','They determine whether the base is Cartesian, spherical or cylindrical','They are three prismatic axes for translating the whole robot base'],['The stated last-three-joint role is wrist orientation.','This reverses the source’s usual position/orientation allocation.','The slide ties those arrangements to the first three joints.','The last three are described as a wrist, not base-translation axes.'])
change(25,3,['Sensor-driven: uses sensors for decisions; intelligent: learns about the environment using AI','Sensor-driven: repeats taught positions unchanged; intelligent: computes joint commands only from a fixed program','Computer-controlled: learns an environmental model by definition; manual: develops programs offline','Intelligent: must be manually guided during replay; computer-controlled: changes behavior only when physically retaught'],['This retains the slide’s distinction between sensor-based decisions and AI-based learning.','Fixed playback belongs to manual teaching, and a fixed program alone does not express the stated learning distinction.','The slide separates ordinary computer programming from AI-based learning; manual teaching is not offline development.','This confuses intelligent and computer-controlled modes with manual teaching/playback.'])
change(27,1,['Position and orientation','Position and linear velocity','Orientation and angular acceleration','Linear velocity and angular velocity'],['Together these describe an object’s spatial pose.','Velocity adds motion rate but does not specify orientation.','Acceleration is a rate-change quantity and does not specify position.','These describe instantaneous motion, not the spatial position and orientation.'])
change(29,2,['The relative position of neighboring links','The absolute end-effector pose in the base frame directly','The relative speed of neighboring links rather than position','The force or torque transmitted across each joint'],['A joint position sensor measures its inter-link coordinate, such as angle or translation.','Base-relative tool pose requires combining joint positions through kinematics.','Speed is a different measured or derived quantity from joint position.','Effort is a different physical quantity from the position described here.'])
change(32,1,['Joint velocities to Cartesian velocities','Joint positions directly to Cartesian positions by the same linear map','Cartesian velocities to joint velocities without requiring any inversion or solvability condition','Joint accelerations directly to Cartesian velocities'],['The stated relation maps joint rates to end-effector Cartesian velocity.','Forward position kinematics is generally nonlinear and is not this velocity relation.','The slide’s displayed direction is joint-to-Cartesian; the reverse can require solving a system and may fail at singularities.','Acceleration and velocity are different derivative orders.'])
change(34,1,['Inverse: desired motion to torque; direct: torque to acceleration and motion','Inverse: torque to motion; direct: desired motion to torque','Inverse: tool pose to joint positions; direct: joint positions to tool pose','Inverse: desired motion to joint coordinates only; direct: torque to tool pose without motion integration'],['These are the source’s inverse- and direct-dynamics directions.','The two directions are reversed.','These describe inverse and forward kinematics, not dynamics.','This omits required actuation effort on the inverse side and the acceleration/integration process on the direct side.'])
change(35,2,['Intermediate locations that the manipulator must pass through','Only the final desired destination','Intermediate velocity values that specify no required location','Obstacle locations that the path must avoid'],['Via points are intermediate required locations along the movement.','The final destination is an endpoint, not the intermediate-location distinction.','A velocity constraint differs from a required intermediate location.','Avoidance points and required pass-through points have opposite roles.'])
change(36,1,['Workspace size and structural stiffness','Workspace size and the controller’s update frequency','Structural stiffness and the task’s desired via-point times','Workspace size and the learned policy’s reward function'],['The slide explicitly pairs these as consequences of the structural design variables.','Workspace size is stated, but controller update frequency is not the second structural outcome named.','Stiffness is stated, but via-point timing belongs to trajectory specification.','Workspace size is stated, but a policy reward is not the other structural outcome identified.'],stem='Which pair does the slide explicitly identify as structural outcomes affected by manipulator design variables?')
change(36,2,['Size, speed, load capability and joint arrangement','Search depth, admissible heuristic, goal test and queue ordering','Learning rate, discount factor, exploration rate and reward function','Via-point timing, stopping rule, frontier ordering and training epochs'],['All four are explicitly listed manipulator design considerations.','These are search-algorithm settings, not the listed mechanical-design group.','These are learning-algorithm settings rather than this slide’s manipulator design factors.','These mix trajectory and algorithm settings rather than the listed physical-design factors.'])
change(38,1,['Rotate the grasped component about a vertical axis','Provide an additional vertical translation after three rotational orientation axes','Tilt the grasped component about a horizontal axis','Rotate the component independently about all three axes'],['The fourth joint adds the one vertical-axis orientation needed by this example.','The source assigns the first three joints to spatial position, not three orientation axes.','Horizontal-axis tilt is not the rotation specified for the flat-board example.','One independent joint cannot supply three independent rotations.'])
change(38,2,['The specialized task needs fewer independent orientation choices','The specialized task needs only two position coordinates but full three-axis orientation','The fourth joint supplies all three independent orientation coordinates','The six-DOF comparison concerns spatial velocity rather than spatial pose'],['The example uses three position coordinates plus one vertical-axis rotation.','The source retains three-dimensional position, and this alternative would require five independent coordinates.','One joint supplies one independent coordinate, not three.','The generic comparison concerns arbitrary position and orientation.'],difficulty='medium')
change(39,1,['Control must also compensate model-parameter errors and suppress disturbances','Dynamics specifies only geometric joint positions and omits forces','A desired trajectory uniquely sets actual torque even when model parameters are wrong','Dynamics computation replaces the need to compare measured and desired motion'],['The source explicitly names parameter errors and disturbances as remaining concerns.','This confuses dynamics with kinematics; dynamics includes forces and torques.','Model error can change the required effort, so nominal trajectory calculations are not sufficient.','Feedback correction remains needed; a model does not replace comparison with measured motion.'],difficulty='medium')
change(40,1,['Joint position/velocity sensors → control algorithm → actuator torque commands','Desired trajectory → fixed torque sequence only, without measured-motion feedback','Joint position sensors → forward kinematics only → desired torque used as the measurement','Measured actuator torque → trajectory generator → no comparison with measured joint motion'],['The stated loop uses measured positions and velocities to compute actuator torque commands.','This is an open-loop feedforward sequence, not the described feedback loop.','The slide describes a controller that uses sensing to compute effort, not this swapped measurement/output chain.','The source specifically includes measured joint motion in the control computation.'])
change(42,2,['Position is controlled in some directions and force in the remaining directions','Position and force independently prescribe incompatible targets in the same constrained direction','Force is controlled in every direction while position targets are omitted','Position is controlled in every direction while contact forces are left uncontrolled'],['This is the source’s complementary direction-wise allocation.','The described scheme separates directions rather than prescribing incompatible targets to the same constrained variable.','This omits the position-controlled part of hybrid control.','This omits the force-controlled part of hybrid control.'],difficulty='medium')
change(43,1,['Perpendicular: force; tangent: motion trajectory','Perpendicular: motion trajectory; tangent: force','Perpendicular and tangent: force only','Perpendicular and tangent: position only'],['Normal force maintains contact while tangential motion performs washing.','This reverses the source’s allocation.','The example retains a prescribed tangential movement.','The example explicitly regulates normal contact force.'],difficulty='medium')
change(44,1,['An interface between the human user and the industrial robot','The physical communication wire between a sensor and its actuator','The low-level torque-control law itself rather than a user programming interface','A method limited to teaching positions by physically guiding the arm'],['The source explicitly describes this human–robot interface role.','A physical link is not the programming language’s stated role.','A language can express requested behavior but is not identical to the underlying servo law.','The source includes offline programming, not only physical manual teaching.'])
change(44,2,['Manipulators are flexible in the sense of being programmable','Manipulators are flexible because every link must deform elastically','Manipulators are flexible only because their base can move','Manipulators are flexible only when they add more than six joints'],['The slide explicitly defines this use of flexible as programmable.','This confuses program flexibility with structural flexibility.','Programmability does not require a mobile base.','The stated distinction does not depend on kinematic redundancy.'],difficulty='medium')
change(46,1,['Desired motions, contact forces and manipulation strategies','Only desired positions, excluding forces and task strategies','Only contact forces, leaving movement outside the language','Only a sequence of joint angles, excluding end-effector motion descriptions'],['The source explicitly includes all three categories.','This is narrower than the slide’s stated scope.','The source includes desired motion as well as forces.','The source allows manipulator/end-effector motion and broader strategies, not only joint-angle lists.'])
for q in b['questions']:
 if q['id'] not in updates:continue
 if q['version']!=1:raise ValueError('Revision already applied; inspect before rerun')
 options,explanations,stem,diff=updates[q['id']];q['version']=2;q['status']='draft';q['reviewIds']=[]
 for o in q['options']:o['text']=options[int(o['id'][1:])-1]
 q['solution']['optionExplanations']={f'o{i+1}':v for i,v in enumerate(explanations)};q['solution']['misconceptions']=[v for i,v in enumerate(explanations) if f'o{i+1}' not in q['correctOptionIds']]
 if stem:q['stem']=stem
 if diff:q['difficulty']=diff
 # Keep concept description and stable IDs, but use the revised question as its display label.
 for c in b['concepts']:
  if c['id'] in q['conceptIds']:c['title']=q['subtopic']+': '+q['stem'][:90]
p.write_text(json.dumps(b,ensure_ascii=False,indent=2))
blind=[{k:q[k] for k in ('id','version','stem','selectionMode','type','difficulty','options','assumptions','citations')} for q in b['questions'] if q['id'] in updates]
(R/'audits/blind-W01-L01-v2.json').write_text(json.dumps(blind,ensure_ascii=False,indent=2))
print('Revised',len(updates),'questions to v2, preserved v1 history.')
